<?php
declare(strict_types=1);
$configFile=__DIR__.'/config.php';
if(!is_file($configFile)){http_response_code(503);exit('Configure config.php antes da atualização.');}
$c=require $configFile;
try{
 $pdo=new PDO(sprintf('mysql:host=%s;dbname=%s;charset=utf8mb4',$c['db_host'],$c['db_name']),$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
 $sql=[
 "CREATE TABLE IF NOT EXISTS farm_equipment (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,property_id INT UNSIGNED NOT NULL,kind ENUM('vehicle','implement','tool','machine') NOT NULL DEFAULT 'machine',name VARCHAR(180) NOT NULL,category VARCHAR(100) NULL,brand VARCHAR(100) NULL,model VARCHAR(100) NULL,identifier VARCHAR(80) NULL,year_manufactured SMALLINT UNSIGNED NULL,hour_meter DECIMAL(12,1) NOT NULL DEFAULT 0,status ENUM('active','maintenance','inactive') NOT NULL DEFAULT 'active',notes TEXT NULL,created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_farm_equipment_property(property_id),CONSTRAINT fk_farm_equipment_property FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE CASCADE,CONSTRAINT fk_farm_equipment_user FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
 "CREATE TABLE IF NOT EXISTS farm_stock_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,property_id INT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,category ENUM('seed','fertilizer','corrective','herbicide','fungicide','insecticide','defensive','veterinary','fuel','lubricant','other') NOT NULL DEFAULT 'other',brand VARCHAR(120) NULL,unit VARCHAR(30) NOT NULL,quantity DECIMAL(14,3) NOT NULL DEFAULT 0,minimum_quantity DECIMAL(14,3) NOT NULL DEFAULT 0,unit_cost DECIMAL(14,2) NOT NULL DEFAULT 0,storage_location VARCHAR(120) NULL,expiry_date DATE NULL,created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_farm_stock_property(property_id),CONSTRAINT fk_farm_stock_property FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE CASCADE,CONSTRAINT fk_farm_stock_user FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
 "CREATE TABLE IF NOT EXISTS farm_stock_movements (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,item_id INT UNSIGNED NOT NULL,property_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NOT NULL,movement_type ENUM('in','out','adjustment') NOT NULL,quantity DECIMAL(14,3) NOT NULL,unit_cost DECIMAL(14,2) NOT NULL DEFAULT 0,movement_date DATE NOT NULL,notes TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_farm_stock_moves_item(item_id,movement_date),CONSTRAINT fk_farm_move_item FOREIGN KEY(item_id) REFERENCES farm_stock_items(id) ON DELETE CASCADE,CONSTRAINT fk_farm_move_property FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE CASCADE,CONSTRAINT fk_farm_move_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
 "CREATE TABLE IF NOT EXISTS farm_equipment_logs (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,equipment_id INT UNSIGNED NOT NULL,property_id INT UNSIGNED NOT NULL,field_id INT UNSIGNED NULL,user_id INT UNSIGNED NOT NULL,operation_date DATE NOT NULL,operation VARCHAR(120) NOT NULL,area_ha DECIMAL(12,2) NULL,hours_used DECIMAL(12,1) NULL,fuel_liters DECIMAL(12,1) NULL,description TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_farm_logs_property_date(property_id,operation_date),CONSTRAINT fk_farm_log_equipment FOREIGN KEY(equipment_id) REFERENCES farm_equipment(id) ON DELETE CASCADE,CONSTRAINT fk_farm_log_property FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE CASCADE,CONSTRAINT fk_farm_log_field FOREIGN KEY(field_id) REFERENCES fields(id) ON DELETE SET NULL,CONSTRAINT fk_farm_log_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
 "CREATE TABLE IF NOT EXISTS farm_maintenance (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,equipment_id INT UNSIGNED NOT NULL,property_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NOT NULL,maintenance_date DATE NOT NULL,maintenance_type ENUM('preventive','corrective') NOT NULL DEFAULT 'preventive',description TEXT NOT NULL,cost DECIMAL(14,2) NOT NULL DEFAULT 0,next_due_date DATE NULL,provider VARCHAR(160) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_farm_maintenance_equipment(equipment_id,maintenance_date),CONSTRAINT fk_farm_maint_equipment FOREIGN KEY(equipment_id) REFERENCES farm_equipment(id) ON DELETE CASCADE,CONSTRAINT fk_farm_maint_property FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE CASCADE,CONSTRAINT fk_farm_maint_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"
 ];
 foreach($sql as $q)$pdo->exec($q);
 header('Content-Type:text/html;charset=utf-8');
 echo '<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><body style="font:16px system-ui;max-width:700px;margin:60px auto;padding:20px;color:#24372b"><h1 style="color:#216b49">Diário de Campo atualizado!</h1><p>As estruturas de frota, estoque, operações e manutenção foram criadas sem apagar os dados existentes.</p><strong>Por segurança, exclua upgrade_diario.php do servidor agora.</strong></body></html>';
}catch(Throwable $e){http_response_code(500);error_log('Agro diario migration: '.$e->getMessage());echo 'Não foi possível atualizar o banco. Consulte o log PHP; não repita a operação antes de verificar o erro.';}
